// Generate TypeScript types from the job-file JSON Schemas (docs/schema, exported by `uv run karaoke schema`).
//   npm run gen:types
// Output: src/types/generated/<name>.ts. Do not edit those files by hand.
import { readdir, readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname, join, basename } from "node:path";
import { fileURLToPath } from "node:url";
import { compile } from "json-schema-to-typescript";

const here = dirname(fileURLToPath(import.meta.url));
const schemaDir = join(here, "..", "..", "docs", "schema");
const outDir = join(here, "..", "src", "types", "generated");
await mkdir(outDir, { recursive: true });

const banner = "/* Generated by scripts/gen-types.mjs from docs/schema/%s. Do not edit. */";
for (const file of (await readdir(schemaDir)).filter((f) => f.endsWith(".schema.json")).sort()) {
  const schema = JSON.parse(await readFile(join(schemaDir, file), "utf8"));
  const ts = await compile(schema, schema.title, {
    bannerComment: banner.replace("%s", file),
    additionalProperties: false,
    style: { singleQuote: false },
  });
  const name = basename(file, ".schema.json");
  await writeFile(join(outDir, `${name}.ts`), ts);
  console.log(`wrote src/types/generated/${name}.ts`);
}
